/**
 * The loading indicator's CSS (M3 Expressive): the seven Material shapes its active indicator
 * morphs through, and the springs that time each morph. Each shape is a clip-path polygon of the
 * same number of points, at the same angles, so CSS interpolates one into the next.
 *
 * style.css holds this output between its "generated by scripts/loadingIndicator.ts" markers.
 * After changing a shape, `npm run loading-indicator` rewrites that block;
 * loadingIndicator.test.ts fails while the two differ.
 *
 * The shapes and timing follow Compose's LoadingIndicator: SoftBurst, Cookie9Sided, Pentagon,
 * Pill, Sunny, Cookie4Sided, Oval; a new morph every 650ms on spring(0.6, 200), each turning the
 * shape a quarter turn, while the whole indicator turns once every 4666ms.
 */

/** A shape's distance from the centre at an angle: 1 at its furthest. */
type Radius = (angle: number) => number;

const POINTS = 72;
export const MORPH_MS = 650;

/** Points around a star: the radius dips to `inner` between them; `sharp` above 1 narrows the points. */
const star =
  (points: number, inner: number, sharp = 1): Radius =>
  (a) =>
    inner + (1 - inner) * ((1 + Math.cos(points * a)) / 2) ** sharp;

/** The radius at each angle of a closed convex outline around the centre, by interpolating between its points. */
function fromOutline(outline: [number, number][]): Radius {
  const polar = outline.map(([x, y]) => ({ a: Math.atan2(y, x), r: Math.hypot(x, y) })).sort((p, q) => p.a - q.a);
  const first = polar[0]!;
  const last = polar[polar.length - 1]!;
  const ring = [{ a: last.a - 2 * Math.PI, r: last.r }, ...polar, { a: first.a + 2 * Math.PI, r: first.r }];
  return (angle) => {
    const a = Math.atan2(Math.sin(angle), Math.cos(angle));
    const i = ring.findIndex((p) => p.a >= a);
    const hi = ring[i]!;
    const lo = ring[i - 1] ?? hi;
    return hi.a === lo.a ? hi.r : lo.r + ((hi.r - lo.r) * (a - lo.a)) / (hi.a - lo.a);
  };
}

/** A convex polygon through `corners` with each corner rounded to `rounding`, as a dense outline. */
function rounded(corners: [number, number][], rounding: number): [number, number][] {
  const n = corners.length;
  const out: [number, number][] = [];
  // Each edge's outward normal; a corner's arc runs from the normal before it to the one after.
  const normal = (i: number) => {
    const [x0, y0] = corners[i]!;
    const [x1, y1] = corners[(i + 1) % n]!;
    return Math.atan2(-(x1 - x0), y1 - y0);
  };
  for (let i = 0; i < n; i++) {
    const [cx, cy] = corners[i]!;
    const from = normal((i + n - 1) % n);
    let to = normal(i);
    while (to < from) to += 2 * Math.PI;
    for (let s = 0; s <= 24; s++) {
      const a = from + ((to - from) * s) / 24;
      out.push([cx + rounding * Math.cos(a), cy + rounding * Math.sin(a)]);
    }
    // The straight edge to the next corner's arc, in steps: fromOutline interpolates between
    // points by angle, which would bow a long edge.
    const [nx, ny] = corners[(i + 1) % n]!;
    const [ox, oy] = [rounding * Math.cos(to), rounding * Math.sin(to)];
    for (let s = 1; s < 48; s++) {
      out.push([cx + ox + ((nx - cx) * s) / 48, cy + oy + ((ny - cy) * s) / 48]);
    }
  }
  return out;
}

const rotate = (points: [number, number][], by: number): [number, number][] =>
  points.map(([x, y]) => [x * Math.cos(by) - y * Math.sin(by), x * Math.sin(by) + y * Math.cos(by)]);

/** A regular polygon of `sides`, its corners rounded, reaching 1 at its furthest. */
function roundedPolygon(sides: number, rounding: number): Radius {
  const r = 1 - rounding;
  const corners = Array.from({ length: sides }, (_, i): [number, number] => {
    const a = -Math.PI / 2 + (2 * Math.PI * i) / sides;
    return [r * Math.cos(a), r * Math.sin(a)];
  });
  return fromOutline(rounded(corners, rounding));
}

/** A capsule along the diagonal: two corners, fully rounded. */
function pill(halfLength: number, radius: number): Radius {
  return fromOutline(rotate(rounded([[-halfLength, 0], [halfLength, 0]], radius), -Math.PI / 4));
}

/** An ellipse along the diagonal. */
function oval(minor: number): Radius {
  const outline = Array.from({ length: 360 }, (_, i): [number, number] => {
    const a = (2 * Math.PI * i) / 360;
    return [Math.cos(a), minor * Math.sin(a)];
  });
  return fromOutline(rotate(outline, -Math.PI / 4));
}

export const SHAPES: Record<string, Radius> = {
  softBurst: star(10, 0.72, 1.6),
  cookie9: star(9, 0.86),
  pentagon: roundedPolygon(5, 0.22),
  pill: pill(0.42, 0.58),
  sunny: star(8, 0.84, 2),
  cookie4: star(4, 0.74),
  oval: oval(0.64),
};

/** A shape as a clip-path polygon, in percentages of its box, starting at the top. */
export function polygon(radius: Radius): string {
  const points = Array.from({ length: POINTS }, (_, k) => {
    const a = -Math.PI / 2 + (2 * Math.PI * k) / POINTS;
    const r = 50 * radius(a);
    const fmt = (v: number) => `${Math.round(v * 10) / 10}%`;
    return `${fmt(50 + r * Math.cos(a))} ${fmt(50 + r * Math.sin(a))}`;
  });
  return `polygon(${points.join(', ')})`;
}

/**
 * A spring's step response (mass 1), sampled over one morph as a CSS linear() easing. `clamp`
 * stops it at 1 the first time it gets there, without the bounce.
 */
export function spring(damping: number, stiffness: number, { clamp = false } = {}): string {
  const w = Math.sqrt(stiffness);
  const wd = w * Math.sqrt(1 - damping ** 2);
  const steps = 26;
  let arrived = false;
  const values = Array.from({ length: steps + 1 }, (_, i) => {
    const t = ((MORPH_MS / 1000) * i) / steps;
    const x = i === steps ? 1 : 1 - Math.exp(-damping * w * t) * (Math.cos(wd * t) + ((damping * w) / wd) * Math.sin(wd * t));
    arrived ||= clamp && x >= 1;
    return arrived ? 1 : Math.round(x * 1000) / 1000;
  });
  return `linear(${values.join(', ')})`;
}

const pct = (i: number, of: number) => `${Math.round((10000 * i) / of) / 100}%`;

export function loadingIndicatorCss(): string {
  const shapes = Object.values(SHAPES).map(polygon);
  const morph = [...shapes, shapes[0]].map((s, i) => `  ${pct(i, shapes.length)} {\n    clip-path: ${s};\n  }`);
  return [
    START,
    ':root {',
    `  --loading-indicator-morph: ${spring(0.6, 200, { clamp: true })};`,
    `  --loading-indicator-turn: ${spring(0.6, 200)};`,
    `  --loading-indicator-shape: ${shapes[0]};`,
    '}',
    '',
    '@keyframes loading-indicator-morph {',
    morph.join('\n\n'),
    '}',
    '',
    END,
  ].join('\n');
}

const START = '/* generated by scripts/loadingIndicator.ts: start */';
const END = '/* generated by scripts/loadingIndicator.ts: end */';

/** style.css with the block between the markers replaced by what this script generates. */
export function withLoadingIndicatorCss(css: string): string {
  const from = css.indexOf(START);
  const to = css.indexOf(END);
  if (from < 0 || to < from) throw new Error('style.css has no loading indicator markers');
  return css.slice(0, from) + loadingIndicatorCss() + css.slice(to + END.length);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const { readFileSync, writeFileSync } = await import('node:fs');
  const path = new URL('../src/style.css', import.meta.url);
  writeFileSync(path, withLoadingIndicatorCss(readFileSync(path, 'utf8')));
}
